import os
import boto3

def compare_cloudwatch_metrics(namespace, metric_name, dimensions_a, dimensions_b, start_time, end_time, period=300, stat="Average"):
    client = boto3.client(
        "cloudwatch",
        region_name=os.getenv("AWS_REGION", "us-east-1")
    )

    query_a = {
        "Id": "resource_a",
        "MetricStat": {
            "Metric": {
                "Namespace": namespace,
                "MetricName": metric_name,
                "Dimensions": dimensions_a,
            },
            "Period": period,
            "Stat": stat,
        },
    }

    query_b = {
        "Id": "resource_b",
        "MetricStat": {
            "Metric": {
                "Namespace": namespace,
                "MetricName": metric_name,
                "Dimensions": dimensions_b,
            },
            "Period": period,
            "Stat": stat,
        },
    }

    response = client.get_metric_data(
        MetricDataQueries=[query_a, query_b],
        StartTime=start_time,
        EndTime=end_time,
    )

    data_map = {item["Id"]: item["Values"] for item in response["MetricDataResults"]}
    ts_map = {item["Id"]: item["Timestamps"] for item in response["MetricDataResults"]}

    values_a = data_map.get("resource_a", [])
    values_b = data_map.get("resource_b", [])
    timestamps = ts_map.get("resource_a", [])

    comparison = {
        "metric_name": metric_name,
        "namespace": namespace,
        "resource_a_values": values_a,
        "resource_b_values": values_b,
        "timestamps": timestamps,
        "differences": []
    }

    min_len = min(len(values_a), len(values_b))
    for i in range(min_len):
        comparison["differences"].append(values_a[i] - values_b[i])

    return comparison
